<script>
(function(){
    var button=document.getElementById('fapReportImageDownload');
    if(!button||!window.ReportTableImageExport)return;
    var source=@json($exportRows);
    var money=function(value){return '$'+Number(value||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});};
    var number=function(value){return Number(value||0).toLocaleString('en-US');};
    var gift=function(value){return value==='available'?'有礼金':(value==='pending_upload'?'未上传礼金图':'未达 $5,000');};
    var consumptionRange=@json($selectedConsumptionRange),consumptionMin=@json($consumptionCustom),consumptionMax=@json($consumptionCustomMax);
    var consumptionNotice=function(){
        if(consumptionRange==='lt_5000')return '消耗低于 $5,000';
        if(consumptionRange==='5000_10000')return '消耗 $5,000 - $10,000';
        if(consumptionRange==='gt_10000')return '消耗高于 $10,000';
        if(consumptionRange==='custom'){
            if(consumptionMin!==null&&consumptionMin!==''&&consumptionMax!==null&&consumptionMax!=='')return '消耗 '+money(consumptionMin)+' - '+money(consumptionMax);
            if(consumptionMin!==null&&consumptionMin!=='')return '消耗不低于 '+money(consumptionMin);
            if(consumptionMax!==null&&consumptionMax!=='')return '消耗不高于 '+money(consumptionMax);
        }
        return '该项目历史总消耗 '+money({{$totals['total_consumption']}});
    };
    button.addEventListener('click',function(){window.ReportTableImageExport.download({
        button:button,title:'服装 AppLovin 业绩报表',subtitle:'日期：{{$dateFrom}} 至 {{$dateTo}}　统计时区：UTC{{$timezone}}',
        topRightText:consumptionNotice(),topRightColor:'#d93025',topRightFontSize:24,redColumns:[10,11],
        summary:'绑定店铺 {{$totals['stores']}}　订单量 {{$totals['orders']}}　该项目历史总业绩 '+money({{$totals['historical_revenue']}})+'　扣除赠金总消耗 '+money({{$totals['deducted_consumption']}})+'　预估总 ROI {{$totals['estimated_total_roi']!==null?number_format($totals['estimated_total_roi'],2):'—'}}',
        headers:['日期','运营部门','运营人员','绑定店铺域名','订单量','营业额($)','广告费($)','ROI','是否有礼金','账号编号','接手前消耗($)','历史总消耗($)','该项目历史总消耗($)','扣减赠金后消耗($)','该项目历史总业绩($)','预估总 ROI'],
        widths:[180,210,130,190,110,155,145,105,150,190,180,190,185,175,185,135],
        rows:source.map(function(row){return [row.date_label,row.department,row.operator,row.store_domain,number(row.orders),money(row.revenue),money(row.ad_spend),row.roi===null?'—':Number(row.roi).toFixed(2),gift(row.gift_status),row.account_numbers||'—',money(row.pre_takeover_consumption),money(row.global_total_consumption),money(row.total_consumption),money(row.deducted_consumption),money(row.historical_revenue),row.all_gift_deducted?'全部由赠金抵扣':(row.estimated_total_roi===null?'—':Number(row.estimated_total_roi).toFixed(2))];}).concat([['合计','','','',number({{$totals['orders']}}),money({{$totals['revenue']}}),money({{$totals['ad_spend']}}),'{{$totals['roi']!==null?number_format($totals['roi'],2):'—'}}','','',money({{$totals['pre_takeover_consumption']}}),money({{$totals['global_total_consumption']}}),money({{$totals['total_consumption']}}),money({{$totals['deducted_consumption']}}),money({{$totals['historical_revenue']}}),'{{$totals['estimated_total_roi']!==null?number_format($totals['estimated_total_roi'],2):'—'}}']]),
        filename:'服装-AppLovin-业绩报表-{{$dateFrom}}-{{$dateTo}}.png'
    });});
})();
</script>
<script>
(function(){
    var table=document.getElementById('fapPerformanceTable'),options=document.getElementById('fapColumnOptions'),menu=document.getElementById('fapColumnMenu'),summary=document.getElementById('fapColumnSummary');
    if(!table||!options||!menu)return;
    var storageKey='fashion-applovin-visible-columns-v1';
    var columns=[
        ['date','日期',true],['department','运营部门',true],['operator','运营人员',true],['store_domain','绑定店铺域名',true],
        ['orders','订单量',true],['revenue','营业额($)',true],['ad_spend','广告费($)',true],['roi','ROI',true],
        ['gift_status','是否有礼金',false],['account_numbers','账号编号',true],['pre_takeover_consumption','接手前消耗($)',false],
        ['global_total_consumption','历史总消耗($)',false],['total_consumption','该项目历史总消耗($)',true],
        ['deducted_consumption','扣减赠金后消耗($)',false],['historical_revenue','该项目历史总业绩($)',false],
        ['estimated_total_roi','预估总 ROI',false],['actions','操作',true]
    ];
    var validKeys=columns.map(function(column){return column[0];});
    var coreColumns=columns.filter(function(column){return column[2];}).map(function(column){return column[0];});
    var defaults=validKeys.slice(),selected=defaults.slice();
    try{
        var saved=JSON.parse(localStorage.getItem(storageKey)||'null');
        if(Array.isArray(saved)){saved=saved.filter(function(key){return validKeys.indexOf(key)!==-1;});if(saved.length)selected=saved;}
    }catch(error){}
    Array.prototype.slice.call(table.querySelectorAll('thead th')).forEach(function(cell,index){cell.dataset.fapColumn=columns[index][0];});
    Array.prototype.slice.call(table.querySelectorAll('tbody tr:not(.fap-empty-row)')).forEach(function(row){
        Array.prototype.slice.call(row.children).forEach(function(cell,index){if(columns[index])cell.dataset.fapColumn=columns[index][0];});
    });
    var totalRow=table.querySelector('.fap-total-row');
    if(totalRow){Array.prototype.slice.call(totalRow.children).slice(1).forEach(function(cell,index){cell.dataset.fapColumn=columns[index+4][0];});}
    columns.forEach(function(column){
        var label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');
        label.className='fap-column-option';input.type='checkbox';input.value=column[0];input.checked=selected.indexOf(column[0])!==-1;text.textContent=column[1];
        label.append(input,text);options.append(label);
    });
    function save(){try{localStorage.setItem(storageKey,JSON.stringify(selected));}catch(error){}}
    function apply(){
        table.classList.add('fap-columns-customized');
        table.querySelectorAll('[data-fap-column]').forEach(function(cell){cell.classList.toggle('fap-column-hidden',selected.indexOf(cell.dataset.fapColumn)===-1);});
        if(totalRow){var lead=totalRow.children[0],leadCount=columns.slice(0,4).filter(function(column){return selected.indexOf(column[0])!==-1;}).length;lead.classList.toggle('fap-column-hidden',leadCount===0);lead.colSpan=Math.max(1,leadCount);}
        var empty=table.querySelector('.fap-empty-row td');if(empty)empty.colSpan=Math.max(1,selected.length);
        options.querySelectorAll('input').forEach(function(input){input.checked=selected.indexOf(input.value)!==-1;});
        if(summary)summary.textContent='已显示 '+selected.length+' / '+columns.length+' 列';
    }
    options.addEventListener('change',function(event){
        if(!event.target.matches('input'))return;
        if(event.target.checked){if(selected.indexOf(event.target.value)===-1)selected.push(event.target.value);}
        else{selected=selected.filter(function(key){return key!==event.target.value;});if(!selected.length){selected=[event.target.value];event.target.checked=true;}}
        save();apply();
    });
    menu.addEventListener('click',function(event){
        event.stopPropagation();var button=event.target.closest('[data-column-action]');if(!button)return;
        selected=button.dataset.columnAction==='core'?coreColumns.slice():defaults.slice();save();apply();
    });
    apply();
})();
</script>
<script>(function(){var size=10;function render(modal,page){var rows=Array.prototype.slice.call(modal.querySelectorAll('.fap-detail-row')),total=rows.length,last=Math.max(1,Math.ceil(total/size));page=Math.max(1,Math.min(page,last));rows.forEach(function(row,i){row.style.display=i>=(page-1)*size&&i<page*size?'':'none';});modal.querySelector('.fap-detail-summary').textContent='显示 '+(total?(page-1)*size+1:0)+'-'+Math.min(page*size,total)+' 条，共 '+total+' 条';var html='';for(var i=1;i<=last;i++)html+='<button class="btn btn-default btn-xs fap-page '+(i===page?'active':'')+'" data-page="'+i+'">'+i+'</button>';modal.querySelector('.fap-detail-pages').innerHTML=html;}$(document).on('show.bs.modal','.fap-detail-modal',function(){render(this,1);});document.addEventListener('click',function(e){var button=e.target.closest('.fap-page');if(button)render(button.closest('.fap-detail-modal'),Number(button.dataset.page));});})();</script>
